const store = $getWorkflowStaticData('global');
if (!store.top10TopicIndex) store.top10TopicIndex = 0;

// Put a topic here when you want to force a specific list.
// Example: '10 cities where renters are getting hit hardest'
const manualTopic = '';

const topicBank = [
  { topic: '10 real estate markets where buyers may have the most leverage right now', iconSet: 'trend', listStyle: 'market ranking', sourceHint: 'Use broad market signals like inventory, price cuts, days on market, and new construction. Avoid exact statistics unless very confident.' },
  { topic: '10 cities where rent pressure feels hardest for young professionals', iconSet: 'money', listStyle: 'city ranking', sourceHint: 'Use broad affordability signals from rent, income, and supply trends. Avoid exact statistics unless very confident.' },
  { topic: '10 things that quietly make a neighborhood more valuable', iconSet: 'home', listStyle: 'educational ranking', sourceHint: 'Evergreen real estate education. No live data required.' },
  { topic: '10 red flags hiding in a home listing', iconSet: 'home', listStyle: 'buyer education', sourceHint: 'Evergreen buyer education. No live data required.' },
  { topic: '10 real estate terms every first-time buyer should know', iconSet: 'home', listStyle: 'beginner education', sourceHint: 'Evergreen education. No live data required.' },
  { topic: '10 property types investors are watching closely', iconSet: 'money', listStyle: 'investment theme ranking', sourceHint: 'Use broad market logic, not exact claims.' },
  { topic: '10 reasons housing feels so expensive even when prices cool', iconSet: 'trend', listStyle: 'explanation ranking', sourceHint: 'Evergreen market explanation with mortgage rates, insurance, taxes, supply, and wages.' },
  { topic: '10 Sun Belt markets real estate people keep watching', iconSet: 'city', listStyle: 'market ranking', sourceHint: 'Use broadly known migration, supply, jobs, and affordability themes. Avoid exact statistics unless very confident.' }
];

let selected;
if (manualTopic.trim()) {
  selected = { topic: manualTopic.trim(), iconSet: 'trend', listStyle: 'manual topic', sourceHint: 'Follow the user topic. Avoid exact statistics unless very confident.' };
} else {
  selected = topicBank[store.top10TopicIndex % topicBank.length];
  store.top10TopicIndex += 1;
}

return [{
  json: {
    selectedTopic: selected.topic,
    iconSet: selected.iconSet,
    listStyle: selected.listStyle,
    sourceHint: selected.sourceHint,
    handle: '@real_estate_rundown',
    brandName: 'Real Estate Rundown',
    pill: 'TOP 10 LIST',
    hashtags: '#realestate #housingmarket #realestateinvesting #firsttimehomebuyer #commercialrealestate #realestatenews #mortgagerates #rentvsbuy #propertyinvestment #housingcrisis #realestatemarket #homebuying #wealthbuilding #realestatetips #investmentproperty'
  }
}];

