parameters.jsCode:
const item = $input.first().json;

const rawText =
  item.output?.[0]?.content?.[0]?.text ||
  item.content?.[0]?.text ||
  item.text ||
  item.content?.parts?.[0]?.text ||
  '';

if (!rawText) throw new Error('No JSON text found in Gemini output.');

const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Could not parse Top 10 JSON. Raw text was: ${cleaned}`);
}

if (!Array.isArray(parsed.items) || parsed.items.length !== 10) {
  throw new Error(`Top 10 output must contain exactly 10 items. Got ${parsed.items?.length || 0}.`);
}

const allowedIcons = ['city', 'money', 'home', 'trend'];
if (!allowedIcons.includes(parsed.iconSet)) parsed.iconSet = $('Choose Top 10 Topic').item.json.iconSet || 'trend';

parsed.title = (parsed.title || '10 Real Estate Trends To Watch').slice(0, 70);
parsed.goldWord = parsed.goldWord || '';
parsed.pill = parsed.pill || 'TOP 10 LIST';
parsed.source = parsed.source || 'Source: Real Estate Rundown analysis';
parsed.handle = '@real_estate_rundown';

parsed.items = parsed.items.slice(0, 10).map((row, i) => ({
  name: String(row.name || `Item ${i + 1}`).slice(0, 28),
  sub: String(row.sub || '').slice(0, 26),
  val: String(row.val || '').slice(0, 18)
}));

parsed.caption = `${parsed.captionHook}\n\n${parsed.captionBody}\n\n${parsed.captionQuestion}\n\n[Created with AI aid]\n${$('Choose Top 10 Topic').item.json.hashtags}`;

parsed.renderPayload = {
  title: parsed.title,
  goldWord: parsed.goldWord,
  pill: parsed.pill,
  source: parsed.source,
  handle: '@real_estate_rundown',
  iconSet: parsed.iconSet,
  items: parsed.items
};

return [{ json: parsed }];
